changeSet.sql:
UPDATE email_login_token SET token = encode(sha256(convert_to(token, 'UTF8')), 'hex');
UPDATE board_invitation SET token = encode(sha256(convert_to(token, 'UTF8')), 'hex');
UPDATE users SET email_verification_token = encode(sha256(convert_to(email_verification_token, 'UTF8')), 'hex')
    WHERE email_verification_token IS NOT NULL;

UPDATE email_login_token SET token = LOWER(RAWTOHEX(HASH('SHA-256', STRINGTOUTF8(token))));
UPDATE board_invitation SET token = LOWER(RAWTOHEX(HASH('SHA-256', STRINGTOUTF8(token))));
UPDATE users SET email_verification_token = LOWER(RAWTOHEX(HASH('SHA-256', STRINGTOUTF8(email_verification_token))))
    WHERE email_verification_token IS NOT NULL;
